n=0
for f in sorted(glob.glob('work/WHITE-L5-es-ES/*.txt')):
    s=open(f,encoding='utf-8').read()
    for a,b in R:
        i=s.find(a)
        if i<0: continue
        j=s.find('.',i)
        s=s[:i]+b+s[j:]; n+=1
    open(f,'w',encoding='utf-8').write(s)
print('replaced',n)
